$ErrorActionPreference = 'Stop'\n\nWrite-Host \"Checking for FFmpeg...\" -ForegroundColor Cyan\n\n$ffmpeg = Get-Command ffmpeg -ErrorAction SilentlyContinue\nif (-not $ffmpeg) {\n    Write-Host \"FFmpeg is not installed or not on PATH.\" -ForegroundColor Yellow\n    Write-Host \"\"\n    Write-Host \"Installation options:\" -ForegroundColor Cyan\n    Write-Host \"1. Chocolatey: choco install ffmpeg\" -ForegroundColor White\n    Write-Host \"2. Scoop: scoop install ffmpeg\" -ForegroundColor White\n    Write-Host \"3. WinGet: winget install BtbN.FFmpeg.Zeranoe\" -ForegroundColor White\n    Write-Host \"4. Direct download: https://www.gyan.dev/ffmpeg/builds/\" -ForegroundColor White\n    Write-Host \"\"\n    Write-Host \"After installing FFmpeg, ensure it's on your PATH and run this script again.\" -ForegroundColor Yellow\n    exit 1\n}\n\nWrite-Host \"FFmpeg found: $($ffmpeg.Source)\" -ForegroundColor Green\n\n$ffprobe = Get-Command ffprobe -ErrorAction SilentlyContinue\nif (-not $ffprobe) {\n    Write-Host \"ffprobe was not found. FFmpeg install may be incomplete.\" -ForegroundColor Red\n    exit 1\n}\n\nWrite-Host \"ffprobe found: $($ffprobe.Source)\" -ForegroundColor Green\nWrite-Host \"Setup complete. You can now trim MP4 files with Trim-Mp4.ps1\" -ForegroundColor Green\n